const BONUS_STORAGE_KEY='taxiDailyBonusSettingsV1',PAYROLL_STORAGE_KEY='taxiDailyPayrollSettingsV1',UI_PREFERENCES_KEY='taxiDailyUiPreferencesV1',APP_SETTINGS_STORAGE_KEY='taxiDailyAppSettingsV1';
