const payrollDefaults={version:1,closingDay:'month-end',rateType:'fixed',fixedRate:'',variableBasis:'tax-excluded',variableRates:[{min:'0',max:'',rate:''}]};
const bonusDefaults={version:4,enabled:false,salesTaxBasis:'tax-included',seasons:{summer:{label:'夏季',startMonth:1,startDay:16,endMonth:7,endDay:15,minDays:'',minSales:'',rateType:'fixed',fixedRate:'',variableRates:[{threshold:'',rate:''}],conditionMode:'and',calculationMethod:'total',calculationBase:''},winter:{label:'冬季',startMonth:7,startDay:16,endMonth:1,endDay:15,minDays:'',minSales:'',rateType:'fixed',fixedRate:'',variableRates:[{threshold:'',rate:''}],conditionMode:'and',calculationMethod:'total',calculationBase:'',linkToSummer:true}}};
const appSettingsDefaults={version:1,features:{analytics:true,intelligence:true},basic:{prefecture:'',trafficArea:''},analysis:{highFareThreshold:'',minimumHighFareCount:'1'},information:{advanceTime:'30',categories:{events:true,domestic:true,international:true,trains:true,cruises:true,highfare:true}},display:{fontSize:'standard',theme:'light'}};
function loadBonusSettings(){try{const saved=JSON.parse(localStorage.getItem(BONUS_STORAGE_KEY)||'null');if(!saved||typeof saved!=='object')return structuredClone(bonusDefaults);const migrateDay=value=>value==='month-end'?'month-end':value??'',migrateSeason=key=>{const old=saved.seasons?.[key]||{},defaults=bonusDefaults.seasons[key],variableRates=Array.isArray(old.variableRates)&&old.variableRates.length?old.variableRates.map(row=>({threshold:row.threshold??'',rate:row.rate??''})):structuredClone(defaults.variableRates);return {...defaults,...old,startDay:migrateDay(old.startDay??defaults.startDay),endDay:migrateDay(old.endDay??defaults.endDay),rateType:old.rateType==='variable'?'variable':'fixed',fixedRate:old.fixedRate??old.rate??'',variableRates,...(key==='winter'?{linkToSummer:typeof old.linkToSummer==='boolean'?old.linkToSummer:false}:{})};};const inheritedBasis=saved.salesTaxBasis||saved.seasons?.summer?.salesTaxBasis||saved.seasons?.winter?.salesTaxBasis;return {version:4,enabled:saved.enabled===true,salesTaxBasis:inheritedBasis==='tax-excluded'?'tax-excluded':'tax-included',seasons:{summer:migrateSeason('summer'),winter:migrateSeason('winter')}};}catch(error){return structuredClone(bonusDefaults);}}
function loadPayrollSettings(){try{const saved=JSON.parse(localStorage.getItem(PAYROLL_STORAGE_KEY)||'null');if(!saved||typeof saved!=='object')return structuredClone(payrollDefaults);return {version:1,closingDay:saved.closingDay==='month-end'||/^(?:[1-9]|[12][0-9]|3[01])$/.test(String(saved.closingDay))?String(saved.closingDay):'month-end',rateType:saved.rateType==='variable'?'variable':'fixed',fixedRate:saved.fixedRate??'',variableBasis:saved.variableBasis==='tax-included'?'tax-included':'tax-excluded',variableRates:Array.isArray(saved.variableRates)&&saved.variableRates.length?saved.variableRates.map(row=>({min:row.min??'',max:row.max??'',rate:row.rate??''})):[{min:'0',max:'',rate:''}]};}catch(error){return structuredClone(payrollDefaults);}}
function loadUiPreferences(){try{const saved=JSON.parse(localStorage.getItem(UI_PREFERENCES_KEY)||'null');return {version:1,hideAmounts:saved?.hideAmounts===true};}catch(error){return {version:1,hideAmounts:false};}}
function loadAppSettings(){try{const saved=JSON.parse(localStorage.getItem(APP_SETTINGS_STORAGE_KEY)||'null');if(!saved||typeof saved!=='object')return structuredClone(appSettingsDefaults);return {version:1,features:{analytics:saved.features?.analytics!==false,intelligence:saved.features?.intelligence!==false},basic:{...appSettingsDefaults.basic,...saved.basic},analysis:{...appSettingsDefaults.analysis,...saved.analysis},information:{...appSettingsDefaults.information,...saved.information,categories:{...appSettingsDefaults.information.categories,...saved.information?.categories}},display:{...appSettingsDefaults.display,...saved.display}};}catch(error){return structuredClone(appSettingsDefaults);}}
let bonusSettings=loadBonusSettings(),payrollSettings=loadPayrollSettings(),uiPreferences=loadUiPreferences(),appSettings=loadAppSettings();
const pageMeta={home:['ホーム',"TODAY'S OVERVIEW"],reports:['日報管理','DAILY REPORTS'],sales:['売上・給与','SALES & PAYROLL'],analytics:['営業分析','BUSINESS ANALYTICS'],intelligence:['営業情報・需要予測','SALES INTELLIGENCE'],settings:['設定','APP SETTINGS']};
let currentView='home',lastFocus=null,settingsReturnView='home',settingsBaseline='',settingsDirty=false,pendingSettingsDestination=null;
let recommendationIndex=0,recommendationTouchStart=null,visibleRecommendations=[];
const handledHighFarePredictionIds=new Set();

function switchView(view){
  if(!pageMeta[view]) return;
  if(!isViewAvailable(view))view='home';
  const leavingSettings=currentView==='settings'&&view!=='settings';
  if(leavingSettings)collapseAllSettingsAccordions();
  currentView=view;
  document.querySelectorAll('.view').forEach(el=>el.classList.toggle('active',el.id===`view-${view}`));
  document.querySelectorAll('[data-view]').forEach(btn=>{const active=btn.dataset.view===view;btn.classList.toggle('active',active);if(btn.closest('.sidebar,.bottom-nav')) active?btn.setAttribute('aria-current','page'):btn.removeAttribute('aria-current');});
  document.getElementById('page-title').textContent=pageMeta[view][0];document.getElementById('page-eyebrow').textContent=pageMeta[view][1];
  window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
  document.getElementById('main-content').focus({preventScroll:true});
  updateSettingsGear();
  setSettingsDirty(settingsDirty);
}

document.addEventListener('click',e=>{
  const nav=e.target.closest('[data-view]');if(nav){e.preventDefault();const target=nav.dataset.view,enteringSettings=target==='settings'&&currentView!=='settings';if(target==='settings'){if(currentView==='settings'&&nav.classList.contains('icon-button'))requestSettingsNavigation(settingsReturnView||'home');else if(currentView!=='settings'){settingsReturnView=currentView;switchView('settings');}}else requestSettingsNavigation(target);if(nav.dataset.settings&&!enteringSettings)openSettingSection(nav.dataset.settings);}
  if(e.target.closest('[data-close-modal]')) closeModals();
  if(e.target.closest('[data-settings-stay]')){pendingSettingsDestination=null;closeModal('settings-leave-modal');}
});

function openModal(id){lastFocus=document.activeElement;const modal=document.getElementById(id);modal.hidden=false;document.body.style.overflow='hidden';setTimeout(()=>modal.querySelector('button,input,select')?.focus(),20);}
function closeModals(){document.querySelectorAll('.modal').forEach(m=>m.hidden=true);document.body.style.overflow='';lastFocus?.focus();}
function closeModal(id){const modal=document.getElementById(id);if(modal)modal.hidden=true;if(!document.querySelector('.modal:not([hidden])'))document.body.style.overflow='';lastFocus?.focus();}
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModals();});
function updateSettingsGear(){const gear=document.querySelector('.topbar .icon-button[data-view="settings"]');if(!gear)return;const back=currentView==='settings';gear.textContent=back?'←':'⚙';gear.setAttribute('aria-label',back?'設定を閉じて前の画面へ戻る':'設定を開く');gear.title=back?'前の画面へ戻る':'設定を開く';gear.classList.toggle('settings-back',back);}
function requestSettingsNavigation(view){if(currentView==='settings'&&view!=='settings'&&settingsDirty){pendingSettingsDestination=view;openModal('settings-leave-modal');return;}switchView(view);}
function isViewAvailable(view){return !((view==='analytics'&&!appSettings.features.analytics)||(view==='intelligence'&&!appSettings.features.intelligence));}

function getTodayInfoPages(source=todayInfoSource){
  const sorted={...source,events:{...source.events,items:[...source.events.items].sort((a,b)=>a.proximity-b.proximity)},international:{...source.international,items:[...source.international.items].sort((a,b)=>a.arrival.localeCompare(b.arrival))},domestic:{...source.domestic,items:[...source.domestic.items].sort((a,b)=>a.arrival.localeCompare(b.arrival))},shinkansen:{...source.shinkansen,items:[...source.shinkansen.items].sort((a,b)=>a.priority-b.priority||a.arrival.localeCompare(b.arrival))},cruises:{...source.cruises,items:[...source.cruises.items].sort((a,b)=>b.capacityValue-a.capacityValue)}};
  const meta={highFare:['高額配車予想','high-fare','￥'],events:['イベント・学会情報','event','◇'],international:['国際線到着情報','international','国'],domestic:['国内線到着情報','domestic','内'],shinkansen:['新幹線到着情報','train','新'],cruises:['クルーズ船入港情報','cruise','船']};
  return TODAY_INFO_ORDER.map(key=>({key,title:meta[key][0],tone:meta[key][1],icon:meta[key][2],...sorted[key]}));
}
function todayInfoEmptyMessage(key,status){if(status==='unavailable')return key==='highFare'?'GPS・日報データ未接続のため、高額配車予想を判定できません':'外部データ未接続のため、現在は対象情報を判定できません';return {highFare:'現在地周辺で、条件に一致する高額配車予想はありません',events:'現在、対象となるイベント情報はありません',international:'今後30分以内の国際線到着予定はありません',domestic:'今後30分以内の国内線到着予定はありません',shinkansen:'今後30分以内の新幹線到着予定はありません',cruises:'本日のクルーズ船入港予定はありません'}[key];}
function todayInfoFields(key,item){if(key==='highFare')return [['乗車地',item.boarding],['降車地',item.alighting],['予想乗車時間',item.predictedTime],['過去の運賃',item.previousFare],['過去の乗車実績',item.occurrences]];if(key==='events')return [['イベント名',item.name],['会場',item.facility],['開始予定',item.start],['終了予定',item.end]];if(key==='international'||key==='domestic')return [['出発地',item.origin],['到着空港',item.airport],['到着予定時刻',item.arrival],['乗客数',item.passengers??'データ未取得']];if(key==='shinkansen')return [['列車名',item.train],['始発駅',item.origin],['到着駅',item.station],['終着駅',item.terminal],['到着予定',item.arrival]];return [['船名',item.ship],['入港場所',item.port],['入港予定',item.arrival],['出港予定',item.departure],['乗客定員',item.capacity],item.actualPassengers&&['実際の乗船人数',item.actualPassengers]].filter(Boolean);}
function otherInfoLabel(page,count){return page.key==='events'?`他のイベント情報も見る（${count}件）`:page.key==='international'||page.key==='domestic'?`他の到着便も見る（${count}便）`:page.key==='shinkansen'?`他の到着列車も見る（${count}本）`:`他のクルーズ船も見る（${count}隻）`;}
function renderTodayInfoPage(page,index,total){const item=page.items[0],extras=page.items.slice(1),empty=!item||page.status==='empty'||page.status==='unavailable';const body=empty?`<div class="today-info-empty"><strong>${todayInfoEmptyMessage(page.key,page.status)}</strong><span>${page.status==='unavailable'?'データ未取得':'取得済み・対象なし'}</span></div>`:`<dl class="today-info-grid">${todayInfoFields(page.key,item).map(([label,value],fieldIndex)=>`<div class="${fieldIndex===0?'primary-field':''}"><dt>${label}</dt><dd>${value}</dd></div>`).join('')}</dl>${page.key==='events'&&item.outsideArea?'<p class="today-info-note">設定交通圏外の情報です。</p>':''}`;const more=!empty&&extras.length&&page.key!=='highFare'?`<button class="button secondary today-info-more" type="button" data-today-info-more="${page.key}">${otherInfoLabel(page,extras.length)}</button>`:'';return `<article class="recommendation-card ${page.tone}" data-recommendation-slide="${index}" aria-roledescription="スライド" aria-label="${index+1}ページ目／${total}ページ"><div class="recommendation-main"><div class="recommendation-type"><span class="recommendation-icon" aria-hidden="true">${page.icon}</span><div><span>UI確認用・架空サンプル</span><h3>${page.title}</h3></div></div>${body}${more}<p class="sample-disclaimer">実際の運行情報・予測結果ではありません。</p></div></article>`;}
function renderHomeRecommendations(source=todayInfoSource){visibleRecommendations=getTodayInfoPages(source);recommendationIndex=0;const track=document.getElementById('recommendation-track'),dots=document.getElementById('recommendation-dots');track.innerHTML=visibleRecommendations.map((page,index)=>renderTodayInfoPage(page,index,visibleRecommendations.length)).join('');dots.innerHTML=visibleRecommendations.map((page,index)=>`<button type="button" data-recommendation-dot="${index}" aria-label="${page.title}を表示"><span class="sr-only">${page.title}</span></button>`).join('');updateHomeRecommendation();bindHomeRecommendationEvents();}
function updateHomeRecommendation(announce=false){
  const track=document.getElementById('recommendation-track');if(!track)return;track.style.transform=`translateX(-${recommendationIndex*100}%)`;
  document.querySelectorAll('[data-recommendation-slide]').forEach((slide,index)=>{const active=index===recommendationIndex;slide.setAttribute('aria-hidden',String(!active));slide.inert=!active;slide.querySelectorAll('button').forEach(button=>button.tabIndex=active?0:-1);});
  document.querySelectorAll('[data-recommendation-dot]').forEach((dot,index)=>{const active=index===recommendationIndex;dot.classList.toggle('active',active);active?dot.setAttribute('aria-current','true'):dot.removeAttribute('aria-current');});
  if(announce&&visibleRecommendations.length)document.getElementById('recommendation-status').textContent=`${recommendationIndex+1}ページ目、${visibleRecommendations[recommendationIndex].title}`;
}
function showRecommendation(index,announce=false){if(visibleRecommendations.length<2)return;recommendationIndex=(index+visibleRecommendations.length)%visibleRecommendations.length;updateHomeRecommendation(announce);}
function bindHomeRecommendationEvents(){
  const root=document.getElementById('recommendation-carousel');if(!root||root.dataset.bound)return;root.dataset.bound='true';
  document.getElementById('recommendation-dots').addEventListener('click',e=>{const dot=e.target.closest('[data-recommendation-dot]');if(dot)showRecommendation(Number(dot.dataset.recommendationDot),true);});
  root.addEventListener('keydown',e=>{if(e.key==='ArrowLeft'){e.preventDefault();showRecommendation(recommendationIndex-1,true);}if(e.key==='ArrowRight'){e.preventDefault();showRecommendation(recommendationIndex+1,true);}});
  root.addEventListener('touchstart',e=>{const t=e.changedTouches[0];recommendationTouchStart={x:t.clientX,y:t.clientY};},{passive:true});
  root.addEventListener('touchend',e=>{const start=recommendationTouchStart,t=e.changedTouches[0];recommendationTouchStart=null;if(start){const dx=t.clientX-start.x,dy=t.clientY-start.y;if(Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy))showRecommendation(recommendationIndex+(dx<0?1:-1),true);}},{passive:true});
  root.addEventListener('click',e=>{const more=e.target.closest('[data-today-info-more]');if(more)openTodayInfoList(more.dataset.todayInfoMore);});
}
function openTodayInfoList(key){
  const page=visibleRecommendations.find(item=>item.key===key),items=page?.items.slice(1);if(!items?.length)return;const date=document.getElementById('detail-date');date.textContent='';date.classList.add('hidden');document.getElementById('detail-title').textContent=`${page.title}の一覧`;
  document.getElementById('detail-content').innerHTML=`<div class="notice warning"><strong>UI確認用の架空サンプル</strong><span>実際の運行情報ではありません。</span></div><div class="today-info-list">${items.map(item=>`<article>${todayInfoFields(key,item).map(([label,value])=>`<div><span>${label}</span><strong>${value}</strong></div>`).join('')}</article>`).join('')}</div><div class="modal-actions"><button class="button secondary" data-close-modal>閉じる</button></div>`;openModal('detail-modal');
}
// 将来の予測結果を受け取る入口。試作品では自動実行せず、通常画面にテスト操作も置かない。
function handleHighFarePrediction(result){const modalOpen=document.querySelector('.modal:not([hidden])');if(!result?.id||result.status!=='matched'||handledHighFarePredictionIds.has(result.id)||currentView!=='home'||document.visibilityState!=='visible'||modalOpen)return false;handledHighFarePredictionIds.add(result.id);showRecommendation(0,true);return true;}

function statusClass(status){return status==='確認済み'?'sample':status==='要確認'?'warning':''}
function formatDateJa(date){const d=new Date(`${date}T00:00:00`);return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日（${'日月火水木金土'[d.getDay()]}）`;}
function renderReports(){
  const query=document.getElementById('report-search').value.trim().toLowerCase(),status=document.getElementById('report-status').value,method=document.getElementById('report-method').value,date=document.getElementById('report-date').value;
  const filtered=reports.filter(r=>(status==='all'||r.status===status)&&(method==='all'||r.method===method)&&(!date||r.date===date)&&`${r.status} ${r.method}`.toLowerCase().includes(query));
  document.getElementById('report-table').innerHTML=filtered.map(r=>`<tr><td><strong>${formatDateJa(r.date)}</strong></td><td><span class="status-chip ${statusClass(r.status)}">${r.status}</span></td><td>${r.method}</td><td>${r.sales}</td><td>${r.rides}回</td><td>${r.cash}</td><td>${r.credit}</td><td><button class="row-button report-detail" data-id="${r.id}">詳細</button></td></tr>`).join('');
  document.getElementById('report-cards').innerHTML=filtered.map(r=>`<article class="report-card"><div><strong>${formatDateJa(r.date)}</strong><span class="status-chip ${statusClass(r.status)}">${r.status}</span></div><dl><div><dt>入力方法</dt><dd>${r.method}</dd></div><div><dt>売上（サンプル）</dt><dd>${r.sales}</dd></div><div><dt>乗車回数</dt><dd>${r.rides}回</dd></div><div><dt>現収／未収</dt><dd>${r.cash}／${r.credit}</dd></div></dl><button class="row-button report-detail" data-id="${r.id}">詳細を見る</button></article>`).join('');
  document.getElementById('report-empty').classList.toggle('hidden',filtered.length>0);
}
document.getElementById('report-search').addEventListener('input',renderReports);document.getElementById('report-status').addEventListener('change',renderReports);document.getElementById('report-method').addEventListener('change',renderReports);document.getElementById('report-date').addEventListener('change',renderReports);
document.getElementById('view-reports').addEventListener('click',e=>{const btn=e.target.closest('.report-detail');if(!btn)return;const r=reports.find(x=>x.id===Number(btn.dataset.id)),date=document.getElementById('detail-date');document.getElementById('detail-title').textContent='日報詳細';date.textContent=formatDateJa(r.date);date.classList.remove('hidden');document.getElementById('detail-content').innerHTML=`<div class="notice info"><strong>サンプル日報</strong><span>正式な保存データではありません。</span></div><div class="detail-grid">${[['確認状態',r.status],['入力方法',r.method],['売上（サンプル）',r.sales],['乗車回数',`${r.rides}回`],['現収',r.cash],['未収',r.credit],['主な営業エリア',r.area],['走行距離',r.distance]].map(x=>`<div class="detail-item"><span>${x[0]}</span><strong>${x[1]}</strong></div>`).join('')}</div><div class="modal-actions"><button class="button secondary" data-close-modal>閉じる</button><button class="button primary" id="mock-edit">編集画面を開く</button></div>`;openModal('detail-modal');document.getElementById('mock-edit').onclick=()=>{closeModals();openReportForm('日報を編集');};});

function openReportForm(title='日報を登録'){document.getElementById('report-modal-title').textContent=title;document.getElementById('registration-methods').classList.remove('hidden');document.getElementById('registration-workspace').innerHTML='';openModal('report-modal');}
document.getElementById('open-report-form').onclick=()=>openReportForm();document.getElementById('home-new-report').onclick=()=>{switchView('reports');openReportForm();};
document.getElementById('registration-methods').addEventListener('click',e=>{const b=e.target.closest('[data-register-method]');if(b)renderRegistration(b.dataset.registerMethod);});
function renderRegistration(method){
  document.getElementById('registration-methods').classList.add('hidden');const root=document.getElementById('registration-workspace');
  if(method==='photo')root.innerHTML=`<button class="back-button" data-registration-back>← 登録方法へ戻る</button><div class="section-heading"><div><span class="overline">PHOTO ENTRY</span><h3>写真から登録</h3></div><span class="status-chip warning">OCR未実装</span></div><p class="lead">選択した写真のファイル名だけを表示します。画像解析や読み取りは行いません。</p><div class="upload-grid"><label class="upload-box"><strong>手書き日報の写真</strong><span>画像を選択</span><input type="file" accept="image/*" data-file-label="daily-file"><small id="daily-file">未選択</small></label><label class="upload-box"><strong>メーターレシートの写真</strong><span>画像を選択</span><input type="file" accept="image/*" data-file-label="meter-file"><small id="meter-file">未選択</small></label></div><div class="notice warning"><strong>読み取りは行いません</strong><span>正式なOCR機能が開発されるまで、読み取り結果確認画面には進めません。</span></div><div class="modal-actions"><button class="button secondary" data-close-modal>キャンセル</button><button class="button primary" data-ocr-next>読み取り結果の確認へ</button></div>`;
  else root.innerHTML=manualForm();
  bindRegistrationControls();
}
function rideFields(index){return `<section class="ride-entry"><div class="section-heading"><h4>乗車記録 ${index}</h4>${index>1?'<button type="button" class="text-link remove-ride">削除</button>':''}</div><div class="form-grid three"><label>降車時刻<input type="time"><small>乗車時刻ではありません</small></label><label>乗車地<input type="text" placeholder="例：博多駅"></label><label>降車地<input type="text" placeholder="例：福岡空港"></label><label>乗車人数<input type="number" min="1" value="1"></label><label>現収<input type="number" min="0" placeholder="円"></label><label>未収<input type="number" min="0" placeholder="円"></label><label>福祉割引<input type="number" min="0" placeholder="円"></label><label>立替金<input type="number" min="0" placeholder="円"></label><label>遠距離割引<input type="number" min="0" placeholder="円"></label><label>備考番号<input type="text"></label></div></section>`;}
function manualForm(){return `<button class="back-button" data-registration-back>← 登録方法へ戻る</button><form id="report-form"><div class="section-heading"><div><span class="overline">MANUAL ENTRY</span><h3>手入力で登録</h3></div><span class="status-chip sample">1勤務分</span></div><div class="form-grid two"><label>営業日<input type="date" required value="2026-10-12"></label><label>勤務メモ<input type="text" placeholder="任意"></label></div><div id="ride-entries">${rideFields(1)}</div><button type="button" class="button secondary" id="add-ride">＋ 乗車記録を追加</button><section class="meter-section"><h3>勤務全体のメーター情報</h3><p>乗車ごとの記録とは分けて入力します。</p><div class="form-grid three"><label>営業回数<input type="number" min="0"></label><label>爾後回数<input type="number" min="0"></label><label>迎車回数<input type="number" min="0"></label><label>営業キロ<input type="number" min="0" step="0.1"></label><label>走行キロ<input type="number" min="0" step="0.1"></label><label>税累計<input type="number" min="0"></label></div></section><div class="modal-actions"><button type="button" class="button secondary" data-close-modal>キャンセル</button><button type="submit" class="button primary">試作品として保存</button></div></form>`;}
function bindRegistrationControls(){
  document.querySelector('[data-registration-back]')?.addEventListener('click',()=>{document.getElementById('registration-methods').classList.remove('hidden');document.getElementById('registration-workspace').innerHTML='';});
  document.querySelectorAll('#registration-workspace input[type=file]').forEach(input=>input.addEventListener('change',()=>{document.getElementById(input.dataset.fileLabel).textContent=input.files[0]?.name||'未選択';}));
  document.querySelector('[data-ocr-next]')?.addEventListener('click',()=>showToast('OCR未実装のため、読み取り結果は表示しません'));
  document.getElementById('add-ride')?.addEventListener('click',()=>{const box=document.getElementById('ride-entries');box.insertAdjacentHTML('beforeend',rideFields(box.children.length+1));});
  document.getElementById('ride-entries')?.addEventListener('click',e=>{if(e.target.closest('.remove-ride'))e.target.closest('.ride-entry').remove();});
  document.getElementById('report-form')?.addEventListener('submit',e=>{e.preventDefault();closeModals();showToast('試作品のため、データは保存されません');});
}

