let sampleMonth=9;function updateMonth(){document.getElementById('sales-month').textContent=`2026年${sampleMonth+1}月`;showToast('表示月の切り替えはサンプルです');}document.getElementById('month-prev').onclick=()=>{sampleMonth=Math.max(0,sampleMonth-1);updateMonth();};document.getElementById('month-next').onclick=()=>{sampleMonth=Math.min(11,sampleMonth+1);updateMonth();};
function renderChart(type='weekday'){
  const d=charts[type],w=620,h=240,p=32,max=100,step=(w-p*2)/(d.values.length-1||1),points=d.values.map((v,i)=>`${p+i*step},${h-p-(v/max)*(h-p*2)}`).join(' ');
  const labels=d.labels.map((l,i)=>`<text x="${p+i*step}" y="${h-7}" text-anchor="middle" fill="#667085" font-size="11">${l}</text>`).join('');
  const guides=[25,50,75,100].map(v=>{const y=h-p-(v/max)*(h-p*2);return `<line x1="${p}" y1="${y}" x2="${w-p}" y2="${y}" stroke="#e7ecf1"/><text x="${p-7}" y="${y+4}" text-anchor="end" fill="#8190a3" font-size="9">${v}</text>`}).join('');
  const dots=d.values.map((v,i)=>`<g class="chart-point" tabindex="0" role="button" data-label="${lSafe(d.labels[i])}" data-value="${v}"><circle cx="${p+i*step}" cy="${h-p-(v/max)*(h-p*2)}" r="10" fill="transparent"/><circle cx="${p+i*step}" cy="${h-p-(v/max)*(h-p*2)}" r="5" fill="#fff" stroke="#0e9f9a" stroke-width="3"/></g>`).join('');
  document.getElementById('analytics-chart').innerHTML=`<svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${d.title}のサンプル折れ線グラフ"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0" stop-color="#0e9f9a" stop-opacity=".3"/><stop offset="1" stop-color="#0e9f9a" stop-opacity="0"/></linearGradient></defs>${guides}<polygon points="${p},${h-p} ${points} ${w-p},${h-p}" fill="url(#area)"/><polyline points="${points}" fill="none" stroke="#0e9f9a" stroke-width="4" stroke-linejoin="round" stroke-linecap="round"/>${dots}${labels}</svg>`;
  document.getElementById('chart-title').textContent=d.title;document.getElementById('chart-overline').textContent=d.overline;document.getElementById('analytics-rides').innerHTML=d.rides;document.getElementById('analytics-average').textContent=d.average;document.getElementById('analytics-trend').textContent=d.trend;
}
function lSafe(s){return String(s).replace(/[&<>"']/g,'')}
document.querySelectorAll('[data-analysis]').forEach(btn=>btn.addEventListener('click',()=>{document.querySelectorAll('[data-analysis]').forEach(b=>{b.classList.toggle('active',b===btn);b.setAttribute('aria-selected',b===btn)});renderChart(btn.dataset.analysis);}));
document.getElementById('analytics-chart').addEventListener('click',e=>showChartPoint(e.target.closest('.chart-point')));document.getElementById('analytics-chart').addEventListener('keydown',e=>{if((e.key==='Enter'||e.key===' ')&&e.target.classList.contains('chart-point'))showChartPoint(e.target);});
