const accordionSections=[
  ['features','機能設定','営業分析・営業情報のON／OFF'],['basic','基本設定','営業地域・交通圏'],['payroll','給与設定','締め日・歩合率・ボーナス'],['report','日報の読み取り','日報・レシートの書式登録'],['analysis','高額運賃の予想設定','予想する金額・回数などの条件'],['information','営業情報の表示','営業情報の表示時間・表示項目のON／OFF'],['display','画面の表示','文字サイズ・画面の色'],['data','データ管理','データの引き継ぎ・出力・削除']
];
function renderUnifiedSettings(){
  document.getElementById('settings-accordion').innerHTML=accordionSections.map(([key,title,desc],index)=>`<article class="accordion-item" data-section="${key}"><h2><button class="accordion-trigger" aria-expanded="false" aria-controls="settings-${key}" id="trigger-${key}"><span class="accordion-number">${String(index+1).padStart(2,'0')}</span><span><strong>${title}</strong><small>${desc}</small></span><i aria-hidden="true">⌄</i></button></h2><div class="accordion-panel" id="settings-${key}" role="region" aria-labelledby="trigger-${key}" hidden>${settingsSectionHtml(key)}</div></article>`).join('');
  bindUnifiedSettings();
  applyFeatureAvailability();
  settingsBaseline=serializeSettingsDraft();setSettingsDirty(false);
}
function settingsSectionHtml(key){
  if(key==='features')return featureSettingsHtml();if(key==='basic')return basicSettingsHtml();if(key==='payroll')return payrollSettingsHtmlV2();if(key==='report')return reportSettingsHtml();if(key==='analysis')return analysisSettingsHtml();if(key==='information')return informationSettingsHtml();if(key==='display')return displaySettingsHtml();return dataSettingsHtml();
}
function bindUnifiedSettings(){
  document.querySelectorAll('.accordion-trigger').forEach(btn=>btn.addEventListener('click',()=>{const item=btn.closest('.accordion-item'),panel=document.getElementById(btn.getAttribute('aria-controls')),open=btn.getAttribute('aria-expanded')==='true';btn.setAttribute('aria-expanded',String(!open));item.classList.toggle('open',!open);panel.hidden=open;}));
  bindPayrollSettingsV4();
  bindTrafficAreaSettings();
  bindSecretSettings();
  bindInformationSettings();
  bindDisplaySettings();
  bindHighFareThreshold();
  document.getElementById('open-reading-settings')?.addEventListener('click',()=>showToast('読み取り設定は未実装です。撮影・OCR・書式保存は行いません'));
  document.querySelectorAll('[data-unavailable]').forEach(btn=>btn.addEventListener('click',()=>showToast(`${btn.dataset.unavailable}は未実装です`)));
  document.getElementById('start-delete-flow')?.addEventListener('click',showDeleteStep1);
  document.getElementById('settings-accordion')?.addEventListener('input',detectSettingsChanges);
  document.getElementById('settings-accordion')?.addEventListener('change',detectSettingsChanges);
}
function openSettingSection(key){
  const item=document.querySelector(`[data-section="${key}"]`);if(!item)return;const trigger=item.querySelector('.accordion-trigger'),panel=item.querySelector('.accordion-panel');trigger.setAttribute('aria-expanded','true');item.classList.add('open');panel.hidden=false;setTimeout(()=>item.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'}),30);
}
function collapseAllSettingsAccordions(){const root=document.getElementById('settings-accordion');root?.classList.add('is-resetting');root?.querySelectorAll('.accordion-item').forEach(item=>{const trigger=item.querySelector('.accordion-trigger'),panel=item.querySelector('.accordion-panel');trigger?.setAttribute('aria-expanded','false');item.classList.remove('open');if(panel)panel.hidden=true;});requestAnimationFrame(()=>root?.classList.remove('is-resetting'));}
