function nextMonth(month){return Number(month)===12?1:Number(month)+1;}
function previousMonth(month){return Number(month)===1?12:Number(month)-1;}
function suggestedWinterPeriod(endMonth,endDay){const month=Number(endMonth);if(!validMonthDay(month,endDay))return {error:'夏季の集計終了日を確認してください'};let start;if(endDay==='month-end')start={month:nextMonth(month),day:1};else{const day=Number(endDay);if(month===2&&day===28)return {error:'2月28日の翌日は年によって変わるため、自動入力できません。「2月・月末」を選ぶか、冬季期間を手動で設定してください'};start=day===daysInRecurringMonth(month)?{month:nextMonth(month),day:1}:{month,day:day+1};}const afterMonth=((start.month-1+6)%12)+1;if(start.day>daysInRecurringMonth(afterMonth))return {error:'6か月後の日付が年によって変わるため、冬季期間を手動で設定してください'};const end=start.day===1?{month:previousMonth(afterMonth),day:'month-end'}:{month:afterMonth,day:start.day-1};return {start,end};}
