function formatRangeAmount(value){return `${Number(value).toLocaleString('ja-JP')}円`;}
function validateVariableRates(rows){if(!rows.length)return {error:'変動賃率を設定してください'};const parsed=rows.map((row,index)=>({index,min:row.min===''?NaN:Number(row.min),max:row.max===''?Infinity:Number(row.max),rate:row.rate===''?NaN:Number(row.rate),unbounded:row.max===''}));for(const row of parsed){if(!Number.isFinite(row.min)||row.min<0)return {error:`${row.index+1}番目の売上下限を0円以上で入力してください`};if(!row.unbounded&&(!Number.isFinite(row.max)||row.max<=row.min))return {error:`${row.index+1}番目の売上上限は下限より大きい金額にしてください`};if(!Number.isFinite(row.rate)||row.rate<0||row.rate>100)return {error:`${row.index+1}番目の賃率を0～100％で入力してください`};}const sorted=[...parsed].sort((a,b)=>a.min-b.min);if(sorted[0].min!==0)return {error:`0円～${formatRangeAmount(sorted[0].min)}未満の売上に対応する賃率がありません`};if(sorted.filter(row=>row.unbounded).length>1)return {error:'上限なしの売上範囲は1つだけ設定してください'};for(let i=0;i<sorted.length-1;i+=1){const current=sorted[i],next=sorted[i+1];if(current.unbounded)return {error:'上限なしの売上範囲より後に別の範囲は設定できません'};if(next.min<current.max)return {error:'売上範囲が重複しています'};if(next.min>current.max)return {error:`${formatRangeAmount(current.max)}～${formatRangeAmount(next.min)}未満の売上に対応する賃率がありません`};}if(!sorted.at(-1).unbounded)return {error:`${formatRangeAmount(sorted.at(-1).max)}以上の売上に対応する賃率がありません`};return {rows:sorted};}
function resolveVariableRate(judgementSales){const validation=validateVariableRates(payrollSettings.variableRates);if(validation.error)return {error:validation.error};const matches=validation.rows.filter(row=>judgementSales>=row.min&&(row.unbounded||judgementSales<row.max));return matches.length===1?{rate:matches[0].rate}:matches.length>1?{error:'売上範囲が重複しています'}:{error:'該当する売上範囲がありません'};}
function calculateSampleSalary(){if(payrollSettings.closingDay!=='month-end')return {status:'期間データ未登録',note:'給与の対象期間データがありません'};const netSales=payrollBaseSales();let rate,note;if(payrollSettings.rateType==='fixed'){rate=Number(payrollSettings.fixedRate);if(payrollSettings.fixedRate===''||!Number.isFinite(rate)||rate<0||rate>100)return {status:'未計算',note:'固定賃率を確認してください'};note=`固定賃率${rate}%`;}else{const judgementSales=payrollSettings.variableBasis==='tax-included'?HOME_SAMPLE_SALES.amount:netSales,resolved=resolveVariableRate(judgementSales);if(resolved.error)return {status:'未計算',note:resolved.error};rate=resolved.rate;note=`変動賃率${rate}%`;}return {amount:Math.round(netSales*(rate/100)),rate,baseSales:netSales,note};}
