function collectBonusSeason(card){const value=name=>card.querySelector(`[data-bonus-field="${name}"]`)?.value??'',dayValue=name=>value(name)==='month-end'?'month-end':Number(value(name)),key=card.dataset.bonusSeason,previous=bonusSettings.seasons[key]||bonusDefaults.seasons[key],linkToSummer=key==='winter'&&document.getElementById('winter-link-to-summer')?.checked===true,currentConditions=bonusConditionsFromCard(card),conditions=linkToSummer?{minDays:previous.minDays??'',minSales:previous.minSales??'',rateType:previous.rateType==='variable'?'variable':'fixed',fixedRate:previous.fixedRate??'',variableRates:structuredClone(previous.variableRates||[{threshold:'',rate:''}])}:currentConditions;return {label:key==='summer'?'夏季':'冬季',startMonth:Number(value('startMonth')),startDay:dayValue('startDay'),endMonth:Number(value('endMonth')),endDay:dayValue('endDay'),...conditions,conditionMode:previous.conditionMode||'and',calculationMethod:previous.calculationMethod||'total',calculationBase:previous.calculationBase??'',salesTaxBasis:document.getElementById('bonus-sales-tax-basis')?.value==='tax-excluded'?'tax-excluded':'tax-included',...(key==='winter'?{linkToSummer}:{})};}
