function validateBonusSeason(card,season){const errors=[];if(!validMonthDay(season.startMonth,season.startDay)||!validMonthDay(season.endMonth,season.endDay))errors.push('実在する月日を選択してください。');if(season.startMonth===season.endMonth&&season.startDay===season.endDay)errors.push('集計開始日と集計終了日は別の日にしてください。');if(season.minDays!==''&&(!Number.isInteger(Number(season.minDays))||Number(season.minDays)<0))errors.push('ボーナス支給に必要な乗務回数は0以上の整数で入力してください。');if(season.rateType==='fixed'){const rate=Number(season.fixedRate);if(season.fixedRate===''||!Number.isFinite(rate)||rate<0||rate>100)errors.push('固定ボーナス率を0～100％で入力してください。');if(season.minSales!==''&&(!Number.isFinite(Number(season.minSales))||Number(season.minSales)<0))errors.push('必要な売上金額は0円以上で入力してください。');}else{const validation=validateBonusVariableRates(season.variableRates);if(validation.error)errors.push(validation.error);}const message=card.querySelector('.bonus-validation');message.textContent=errors.join(' ');message.classList.toggle('hidden',!errors.length);return errors.length===0;}
function bonusBaseSales(grossSales=getBonusPeriodTotals().grossSales){return bonusSettings.salesTaxBasis==='tax-excluded'?calculateTaxExclusiveSales(grossSales):grossSales;}
function calculateSampleBonus(season,sample=getBonusPeriodTotals()){const sales=Math.round(bonusBaseSales(sample.grossSales)),duties=Number(sample.duties),requiredDuties=season.minDays===''?null:Number(season.minDays),remainingDuties=requiredDuties===null?null:Math.max(0,requiredDuties-duties),dutyConditionMet=remainingDuties===null||remainingDuties===0;let rate=0,nextRate=null,highestRateReached=false,salesConditionMet=true;if(season.rateType==='variable'){const validation=validateBonusVariableRates(season.variableRates);if(validation.error)return {status:'未計算',sales,duties,remainingDuties,note:validation.error};const matched=validation.rows.filter(row=>sales>=row.threshold).at(-1);rate=matched?.rate??0;salesConditionMet=Boolean(matched);nextRate=validation.rows.find(row=>row.threshold>sales)||null;highestRateReached=Boolean(matched)&&!nextRate;}else{rate=Number(season.fixedRate);if(season.fixedRate===''||!Number.isFinite(rate)||rate<0||rate>100)return {status:'未計算',sales,duties,remainingDuties,note:'固定ボーナス率を確認してください'};salesConditionMet=season.minSales===''||sales>=Number(season.minSales);}const amount=Math.floor(sales*(rate/100)),eligible=dutyConditionMet&&salesConditionMet;return {amount,rate,sales,duties,remainingDuties,dutyConditionMet,salesConditionMet,eligible,nextRate,highestRateReached,isSample:true,note:`${eligible?'支給条件達成':'支給条件未達の参考見込額'}・${sample.label}`};}
function updateHomeBonusLayout(){const grid=document.getElementById('home-sales-grid'),bonus=document.getElementById('home-bonus-card');if(!grid||!bonus)return;grid.classList.toggle('bonus-off',!bonusSettings.enabled);grid.classList.toggle('bonus-on',bonusSettings.enabled);bonus.classList.toggle('hidden',!bonusSettings.enabled);if(!bonusSettings.enabled)return;const season=effectiveBonusSeason(bonusSettings,'summer'),result=calculateSampleBonus(season),amount=bonus.querySelector('strong'),duty=document.getElementById('home-bonus-duty-progress'),rateProgress=document.getElementById('home-bonus-rate-progress'),basis=bonusSettings.salesTaxBasis==='tax-excluded'?'税抜':'税込';amount.textContent=Number.isFinite(result.amount)?`¥${result.amount.toLocaleString('ja-JP')}`:result.status;Number.isFinite(result.amount)?amount.dataset.privateAmount='':delete amount.dataset.privateAmount;if(duty)duty.textContent=result.remainingDuties===null?'':result.remainingDuties>0?`ボーナス支給まで${result.remainingDuties}乗務`:'乗務回数の条件達成';if(rateProgress){if(!Number.isFinite(result.amount))rateProgress.textContent=result.note;else if(season.rateType==='fixed')rateProgress.innerHTML=`設定ボーナス率 <strong>${result.rate}%</strong>（${basis}）`;else if(result.nextRate){const remaining=Math.ceil(result.nextRate.threshold-result.sales);rateProgress.innerHTML=`ボーナス率<strong>${result.nextRate.rate}%</strong>まで <span class="bonus-rate-target"><span class="bonus-rate-amount" data-private-amount>¥${remaining.toLocaleString('ja-JP')}</span>（${basis}）</span>`;}else if(result.highestRateReached)rateProgress.innerHTML=`最高ボーナス率<strong>${result.rate}%</strong>達成`;else rateProgress.textContent='売上基準を確認してください';}}
