function bonusPeriodText(season){const wraps=recurringDayOrder(season.endMonth,season.endDay)<recurringDayOrder(season.startMonth,season.startDay);return `${season.startMonth}月${bonusDayText(season.startDay)}～${wraps?'翌年':''}${season.endMonth}月${bonusDayText(season.endDay)}`;}
function formattedSettingAmount(value){return value===''?'未設定':`¥${Number(value).toLocaleString('ja-JP')}`;}
function openBonusDetails(){const season=effectiveBonusSeason(bonusSettings,'summer'),result=calculateSampleBonus(season),date=document.getElementById('detail-date'),basis=bonusSettings.salesTaxBasis==='tax-excluded'?'税抜売上':'税込売上',salesSetting=season.rateType==='fixed'&&season.minSales!==''?`<span data-private-amount>${formattedSettingAmount(season.minSales)}</span>`:'未設定';date.textContent='';date.classList.add('hidden');document.getElementById('detail-title').textContent='夏季ボーナス詳細';document.getElementById('detail-content').innerHTML=`<div class="notice warning"><strong>サンプル計算</strong><span>正式な日報実績ではなく、UI確認用の集計期間累計売上・乗務回数を使用しています。</span></div><section class="bonus-modal-section"><h3>設定内容</h3><div class="detail-grid"><div class="detail-item"><span>区分</span><strong>夏季</strong></div><div class="detail-item"><span>集計期間</span><strong>${bonusPeriodText(season)}</strong></div><div class="detail-item"><span>必要な乗務回数</span><strong>${season.minDays===''?'未設定':`${season.minDays}回`}</strong></div><div class="detail-item"><span>必要な売上金額</span><strong>${salesSetting}</strong></div><div class="detail-item"><span>ボーナス率</span><strong>${season.rateType==='variable'?'変動':'固定'}</strong></div><div class="detail-item"><span>計算対象売上</span><strong>${basis}</strong></div></div></section><section class="bonus-modal-section"><h3>サンプル計算結果</h3><div class="detail-grid"><div class="detail-item"><span>乗務実績</span><strong>${result.duties}回（サンプル）</strong></div><div class="detail-item"><span>集計期間累計売上</span><strong data-private-amount>¥${Math.round(result.sales).toLocaleString('ja-JP')}</strong></div><div class="detail-item wide"><span>現時点の参考見込額</span><strong ${Number.isFinite(result.amount)?'data-private-amount':''}>${Number.isFinite(result.amount)?`¥${result.amount.toLocaleString('ja-JP')}`:result.status}</strong><small>${result.note}</small></div></div></section><div class="notice compact"><span>条件を満たしても、会社による最終査定がある可能性があります。支給確定を示すものではありません。</span></div><div class="modal-actions"><button class="button secondary" data-close-modal>閉じる</button></div>`;openModal('detail-modal');}
function bindHomeFinancialControls(){document.getElementById('amount-visibility-toggle')?.addEventListener('change',e=>{uiPreferences.hideAmounts=!e.target.checked;applyAmountVisibility();persistUiPreferences();showToast(uiPreferences.hideAmounts?'金額を非表示にしました':'金額を表示しました');});document.getElementById('home-bonus-card')?.addEventListener('click',openBonusDetails);updateHomeBonusLayout();updateHomeSalesSummary();updateHomeSalary();applyAmountVisibility();}
function bindTrafficAreaSettings(){
  const prefecture=document.getElementById('prefecture'),area=document.getElementById('traffic-area'),help=document.getElementById('traffic-area-help');if(!prefecture||!area||!help)return;
  const updateAreas=(preferred='')=>{
    const selected=prefecture.value,areas=trafficAreasByPrefecture[selected];
    area.value='';
    if(!selected){area.innerHTML='<option value="">営業地域を選択してください</option>';area.disabled=true;help.textContent='営業地域を選択すると、登録済みの交通圏候補を表示します。';return;}
    if(!areas){area.innerHTML='<option value="">この地域の交通圏データは準備中です</option>';area.disabled=true;help.textContent='正式な公的資料を確認後に追加します。未確認の交通圏は選択できません。';return;}
    area.innerHTML=`<option value="">交通圏を選択</option>${areas.map(item=>`<option value="${item.value}">${item.label}（仮データ）</option>`).join('')}`;
    area.disabled=false;area.value=areas.some(item=>item.value===preferred)?preferred:'';help.textContent='福岡県の候補はUI確認用の仮データです。正式な全国交通圏マスターではありません。';
  };
  prefecture.addEventListener('change',()=>updateAreas(''));
  updateAreas(appSettings.basic.trafficArea);
}
function bindSecretSettings(){
  const selects=[...document.querySelectorAll('.secret-question')];
  function syncQuestions(){const selected=selects.map(s=>s.value).filter(Boolean);selects.forEach(select=>[...select.options].forEach(option=>{option.disabled=Boolean(option.value&&option.value!==select.value&&selected.includes(option.value));}));}
  selects.forEach(select=>select.addEventListener('change',syncQuestions));
  document.querySelectorAll('.toggle-secret').forEach(btn=>btn.addEventListener('click',()=>{const input=btn.previousElementSibling,show=input.type==='password';input.type=show?'text':'password';btn.textContent=show?'隠す':'表示';btn.setAttribute('aria-label',show?'答えを隠す':'答えを表示');}));
  document.getElementById('register-secret')?.addEventListener('click',()=>{const questions=selects.map(s=>s.value),answers=[...document.querySelectorAll('.secret-answer')].map(i=>i.value.trim());if(questions.some(q=>!q)||new Set(questions).size!==3||answers.some(a=>!a)){showToast('異なる3つの質問と、それぞれの答えを入力してください');return;}prototypeSecret={registered:true,questions:[...questions]};document.getElementById('secret-status').textContent='試作登録済み';document.getElementById('secret-status').className='status-chip sample';showToast('試作状態として登録しました。保存・認証は行われません');});
}
function bindInformationSettings(){
  const master=document.getElementById('all-info'),items=[...document.querySelectorAll('.info-toggle')];if(!master)return;
  master.addEventListener('change',()=>items.forEach(item=>item.checked=master.checked));
  items.forEach(item=>item.addEventListener('change',()=>master.checked=items.every(i=>i.checked)));
}
